export function buildPartnershipsSchedule(startISO = null) {
  return buildScheduleFor(PARTNERSHIPS_MODULES, startISO, PARTNERSHIPS_META.cadenceDays);
}

export function partnershipsProgressSummary(progress = {}) {
  return progressSummaryFor(PARTNERSHIPS_MODULES, progress);
}

export function exportPartnershipsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: PARTNERSHIPS_META,
    modules: buildPartnershipsSchedule(startISO),
    sessionFlow: PARTNERSHIPS_SESSION_FLOW,
  }, startISO);
}

