export function partnershipsRefs() {
  const seen = new Set();
  for (const m of PARTNERSHIPS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((PARTNERSHIPS_META.wordFirst && PARTNERSHIPS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

